import sys, json
for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
        if d.get('type') == 'assistant' and d.get('subtype') == 'tool_use':
            msg = d.get('message','')
            if isinstance(msg, dict):
                tool = msg.get('name','')
                inp = msg.get('input',{})
                if tool == 'Write':
                    print(f'WRITE: {inp.get(\"file_path\",\"\")} ({len(inp.get(\"content\",\"\"))} chars)')
                elif tool == 'Bash':
                    cmd = inp.get('command','')[:120]
                    print(f'BASH: {cmd}')
                elif tool == 'Read':
                    print(f'READ: {inp.get(\"file_path\",\"\")}')
                else:
                    print(f'TOOL: {tool}')
        elif d.get('type') == 'assistant' and d.get('subtype') == 'text':
            msg = d.get('message','')
            if msg and len(msg) < 200:
                print(f'TEXT: {msg}')
    except:
        pass
" 2>/dev/null
